import itertools
from collections import deque

def check_graph(n, edges):
    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    # Check vertex connectivity >= 2
    # A graph has vertex connectivity >= 2 if it's connected and has no cut vertices
    # We can check by removing each vertex and seeing if the graph remains connected

    def is_connected(removed_vertex=None):
        visited = set()
        start = 0 if removed_vertex != 0 else 1
        if start >= n:
            return True
        queue = deque([start])
        visited.add(start)
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v != removed_vertex and v not in visited:
                    visited.add(v)
                    queue.append(v)
        # Check if all vertices except removed_vertex are visited
        for i in range(n):
            if i != removed_vertex and i not in visited:
                return False
        return True

    # Check connectivity
    if not is_connected():
        return False, "Graph is not connected"

    for v in range(n):
        if not is_connected(v):
            return False, f"Vertex {v} is a cut vertex"

    # Check maximum independent set size <= 5
    # Use brute force for small graphs
    max_indep = 0
    for r in range(n + 1):
        for subset in itertools.combinations(range(n), r):
            # Check if subset is independent
            is_indep = True
            for i in range(len(subset)):
                for j in range(i + 1, len(subset)):
                    if subset[j] in adj[subset[i]]:
                        is_indep = False
                        break
                if not is_indep:
                    break
            if is_indep:
                max_indep = max(max_indep, r)

    if max_indep > 5:
        return False, f"Maximum independent set size is {max_indep}"

    return True, f"Valid graph with max independent set size {max_indep}"

# Generate K_11
n = 11
edges = list(itertools.combinations(range(n), 2))
print(f"Number of edges: {len(edges)}")
valid, msg = check_graph(n, edges)
print(f"K_11: {msg}")
